const incoming = items && items[0] && items[0].json ? items[0].json : {};
const body = incoming.body || incoming;
const requestText = String(body.orchestrator_request || body.request || body.message || 'clasificar y enrutar solicitud del proyecto');
const dryRun = body.dry_run !== false;
const prompt = [
  'Actua como AGENT-ORCH-001 para el proyecto Invernadero Central.',
  'Solicitud: ' + requestText + '.',
  'Clasifica la solicitud, aplica reglas de autoridad y recomienda el agente/workflow competente. No hagas trabajo especializado.',
  'Para trabajo tecnico que toque codigo, repos, API, MQTT, DB, eventos, frontend/backend, infraestructura o CI/CD, enruta primero a AGENT-DISC-001.',
  'Si Discovery recomienda contrato compartido, enruta a AGENT-CONTRACT-001 antes de Refinement.',
  'Pipeline esperado cuando aplique: Intake -> Knowledge -> Discovery -> Contract Decision -> Refinement -> Review -> QA -> Human Gate.',
  'Usa contexto versionado del repo central y cita fuentes cuando aplique.',
  'Trabaja en modo DRAFT; no persistas, no muevas Kanban, no marques DONE, no edites HU congeladas, no compres, no despliegues criticamente ni controles sistemas fisicos sin aprobacion humana.',
  'Devuelve salida util para humano/n8n con summary, recommended_actions, evidence_expected, risks, source_refs y one_question si aplica.'
].join(' ');
return [{ json: { agent: 'project-orchestrator', workspace: 'central', prompt, mode: 'wf-orchestrator-001', approval_required: true, dry_run: dryRun, metadata: { task_id: 'WF-ORCHESTRATOR-001', agent_id: 'AGENT-ORCH-001', requested_by: body.requested_by || 'chat-gateway' } } }];
